// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address target, uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(target != address(0));
        burnAmount = bound(burnAmount, 0, c.balanceOf(c.owner()));
        vm.prank(c.owner());
        c.mintToken(target, mintAmount);
        vm.prank(c.owner());
        c.burn(burnAmount);
        assertTrue(c.totalSupply() <= c.balanceOf(c.owner()) + c.balanceOf(target));
    }
}

